import{_ as o,c as t,o as e,ag as l}from"./chunks/framework.DQvKz0xt.js";const p=JSON.parse('{"title":"布局工具 (Tools) - Rive 编辑器","description":"布局 (Layouts) Rive 提供了多种布局工具来构建你的响应式 UI。","frontmatter":{"title":"布局工具 (Tools) - Rive 编辑器","description":"布局 (Layouts) Rive 提供了多种布局工具来构建你的响应式 UI。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 布局, 布局工具"}]]},"headers":[],"relativePath":"editor/layouts/layout-tools.md","filePath":"editor/layouts/layout-tools.md","lastUpdated":1774838907000}'),i={name:"editor/layouts/layout-tools.md"};function r(d,a,s,n,u,h){return e(),t("div",null,[...a[0]||(a[0]=[l('<p>布局 (Layouts)</p><h1 id="布局工具-tools" tabindex="-1">布局工具 (Tools) <a class="header-anchor" href="#布局工具-tools" aria-label="Permalink to &quot;布局工具 (Tools)&quot;">​</a></h1><p>Rive 提供了多种布局工具来构建你的响应式 UI。</p><h2 id="​-开始使用布局" tabindex="-1"><a href="#getting-started-with-layouts">​</a> 开始使用布局 <a class="header-anchor" href="#​-开始使用布局" aria-label="Permalink to &quot;[​](#getting-started-with-layouts) 开始使用布局&quot;">​</a></h2><p>可以通过以下几种方式将布局添加到你的设计中：</p><ul><li>排列工具菜单中的布局工具</li><li>包裹到布局 (Wrap in Layout)</li><li>添加子布局 (Add Child Layout)</li><li>拖放布局</li></ul><hr><h3 id="​-排列工具菜单中的布局工具" tabindex="-1"><a href="#layout-tools-in-the-arrangement-tools-menu">​</a> 排列工具菜单中的布局工具 <a class="header-anchor" href="#​-排列工具菜单中的布局工具" aria-label="Permalink to &quot;[​](#layout-tools-in-the-arrangement-tools-menu) 排列工具菜单中的布局工具&quot;">​</a></h3><ul><li><strong>布局 (Layout)</strong>：单个布局容器。选中工具并在画板上拖动即可。直接拖动创建绝对布局，拖动到现有布局上创建相对子布局。</li><li><strong>行/列 (Row/Column)</strong>：创建布局的同时包含一组初始子项。拖动时可以使用数字键或上下键定义子项数量。这些子项默认设置为“填充 (Fill)”。</li></ul><h3 id="​-包裹到布局-wrap-in-layout" tabindex="-1"><a href="#wrap-in-layout">​</a> 包裹到布局 (Wrap in Layout) <a class="header-anchor" href="#​-包裹到布局-wrap-in-layout" aria-label="Permalink to &quot;[​](#wrap-in-layout) 包裹到布局 (Wrap in Layout)&quot;">​</a></h3><p>你可以将现有对象包裹到布局中：</p><ul><li>右键点击舞台或层级面板，选择 <code>Wrap in</code> &gt; <code>Layout</code>。</li><li>使用快捷键 <code>Shift + L</code>。</li><li>使用检查器中的 <code>Layout selection</code> 按钮。</li></ul><h3 id="​-添加子布局" tabindex="-1"><a href="#add-child-layout">​</a> 添加子布局 <a class="header-anchor" href="#​-添加子布局" aria-label="Permalink to &quot;[​](#add-child-layout) 添加子布局&quot;">​</a></h3><p>选中布局时，检查器会显示 <code>Add Child Layout</code> 按钮，点击即可添加一个默认填充父级的子布局。</p><h3 id="​-拖放布局" tabindex="-1"><a href="#dragging-and-dropping-layouts">​</a> 拖放布局 <a class="header-anchor" href="#​-拖放布局" aria-label="Permalink to &quot;[​](#dragging-and-dropping-layouts) 拖放布局&quot;">​</a></h3><p>你可以随时在层级面板或舞台上通过拖放来嵌套布局。在舞台上拖动时，指示器会显示插入位置。</p><p><a href="/docs/editor/layouts/overview">概览 (Overview)</a><a href="/docs/editor/layouts/layout-parameters">参数 (Parameters)</a></p>',17)])])}const y=o(i,[["render",r]]);export{p as __pageData,y as default};
